(function(){"use strict";if(!("serviceWorker"in navigator))return;window.addEventListener("load",function(){navigator.serviceWorker.register("/sports/service-worker.js",{scope:"/sports/"}).catch(function(){})});let e=null;const t=Array.from(document.querySelectorAll("[data-install-sports]"));window.addEventListener("beforeinstallprompt",function(n){n.preventDefault(),e=n,t.forEach(function(e){e.hidden=!1})}),t.forEach(function(n){n.addEventListener("click",function(){if(!e)return;e.prompt(),e.userChoice.finally(function(){e=null,t.forEach(function(e){e.hidden=!0})})})}),window.addEventListener("appinstalled",function(){e=null,t.forEach(function(e){e.hidden=!0})})})()